<?php
namespace Tests\Feature;
use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\Storage;use Tests\TestCase;
class PaymentModerationTest extends TestCase{use RefreshDatabase;public function test_payment_proof_can_be_approved_and_job_published():void{Storage::fake('local');[$companyUser,$job]=$this->submittedJob();$payment=$this->actingAs($companyUser,'sanctum')->postJson("/api/v1/company/jobs/{$job}/payment")->assertCreated()->json('data');$this->actingAs($companyUser,'sanctum')->post("/api/v1/company/jobs/{$job}/payment/proof",['proof'=>UploadedFile::fake()->create('comprobante.pdf',100,'application/pdf')],['Accept'=>'application/json'])->assertOk()->assertJsonPath('data.status','proof_submitted');$admin=User::factory()->create(['is_admin'=>true]);$this->actingAs($admin,'sanctum')->getJson('/api/v1/admin/moderation')->assertOk()->assertJsonCount(1,'data.payments');$this->actingAs($admin,'sanctum')->postJson("/api/v1/admin/payments/{$payment['id']}/review",['decision'=>'approve'])->assertOk();$this->actingAs($admin,'sanctum')->postJson("/api/v1/admin/jobs/{$job}/review",['decision'=>'approve'])->assertOk()->assertJsonPath('data.status','active');$this->getJson('/api/v1/jobs')->assertOk()->assertJsonPath('data.data.0.id',$job);}public function test_non_admin_cannot_moderate():void{$this->actingAs(User::factory()->create(),'sanctum')->getJson('/api/v1/admin/moderation')->assertForbidden();}private function submittedJob():array{$user=User::factory()->create(['account_type'=>'company']);$this->actingAs($user,'sanctum')->getJson('/api/v1/company/profile');$quote=$this->actingAs($user,'sanctum')->postJson('/api/v1/company/quotations',['vacancies'=>1,'duration'=>30,'applications'=>'50','urgency'=>'normal','visibility'=>'normal','classification'=>'manual','diffusion'=>[]])->json('data.reference');$payload=['quotation_reference'=>$quote,'title'=>'Desarrollador Backend Laravel','summary'=>'Buscamos una persona para ampliar nuestro equipo de desarrollo.','description'=>str_repeat('Participará en el diseño y construcción de servicios confiables para nuestros productos digitales. ',3),'requirements'=>['PHP','Laravel','PostgreSQL'],'benefits'=>['Seguro médico'],'location'=>'Santo Domingo','modality'=>'Híbrido','contract_type'=>'Tiempo completo','salary_min'=>80000,'salary_max'=>110000,'currency'=>'DOP'];$job=$this->actingAs($user,'sanctum')->postJson('/api/v1/company/jobs',$payload)->json('data.id');$this->actingAs($user,'sanctum')->postJson("/api/v1/company/jobs/{$job}/submit")->assertOk();return[$user,$job];}}
